#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <functional>
#include <future>
#include <mutex>
#include <regex>
#include <algorithm>
#include <sstream>

namespace oauth {

struct RedirectConfig {
    std::vector<std::string> allowed_origins;
    bool enforce_https;
    bool allow_subdomains;
};

struct AuthRequest {
    std::string client_id;
    std::string redirect_uri;
    std::string state;
    std::string scope;
};

struct ValidationResult {
    bool valid;
    std::string error;
    std::string normalized_uri;
};

class UriNormalizer {
public:
    static std::string decode_percent(const std::string& uri) {
        std::string result;
        for (size_t i = 0; i < uri.size(); ++i) {
            if (uri[i] == '%' && i + 2 < uri.size()) {
                int hex_val = 0;
                std::istringstream iss(uri.substr(i + 1, 2));
                iss >> std::hex >> hex_val;
                result += static_cast<char>(hex_val);
                i += 2;
            } else {
                result += uri[i];
            }
        }
        return result;
    }

    static std::string normalize_path(const std::string& path) {
        std::vector<std::string> segments;
        std::istringstream stream(path);
        std::string segment;
        while (std::getline(stream, segment, '/')) {
            if (segment == "..") {
                if (!segments.empty()) segments.pop_back();
            } else if (segment != "." && !segment.empty()) {
                segments.push_back(segment);
            }
        }
        std::string result = "/";
        for (size_t i = 0; i < segments.size(); ++i) {
            result += segments[i];
            if (i < segments.size() - 1) result += "/";
        }
        return result;
    }

    static std::string extract_host(const std::string& uri) {
        size_t scheme_end = uri.find("://");
        if (scheme_end == std::string::npos) return "";
        size_t host_start = scheme_end + 3;
        size_t host_end = uri.find('/', host_start);
        if (host_end == std::string::npos) host_end = uri.size();
        // Strip userinfo (RFC 3986 section 3.2.1)
        std::string authority = uri.substr(host_start, host_end - host_start);
        size_t at_pos = authority.find('@');
        if (at_pos != std::string::npos) {
            authority = authority.substr(at_pos + 1);
        }
        return authority;
    }

    static std::string extract_scheme(const std::string& uri) {
        size_t pos = uri.find("://");
        if (pos == std::string::npos) return "";
        return uri.substr(0, pos);
    }
};

class RedirectValidator {
private:
    RedirectConfig config_;
    mutable std::mutex mtx_;
    std::map<std::string, ValidationResult> cache_;

    bool host_matches_origin(const std::string& host, const std::string& origin) const {
        if (host == origin) return true;
        if (config_.allow_subdomains) {
            std::string suffix = "." + origin;
            if (host.size() > suffix.size() &&
                host.compare(host.size() - suffix.size(), suffix.size(), suffix) == 0) {
                return true;
            }
        }
        return false;
    }

    ValidationResult validate_internal(const std::string& redirect_uri) const {
        std::string decoded = UriNormalizer::decode_percent(redirect_uri);
        std::string scheme = UriNormalizer::extract_scheme(decoded);
        std::string host = UriNormalizer::extract_host(decoded);

        if (config_.enforce_https && scheme != "https") {
            return {false, "HTTPS required", ""};
        }

        // Convert host to lowercase for comparison
        std::string lower_host = host;
        std::transform(lower_host.begin(), lower_host.end(), lower_host.begin(), ::tolower);

        for (const auto& origin : config_.allowed_origins) {
            std::string lower_origin = origin;
            std::transform(lower_origin.begin(), lower_origin.end(), lower_origin.begin(), ::tolower);
            if (host_matches_origin(lower_host, lower_origin)) {
                return {true, "", decoded};
            }
        }
        return {false, "Origin not allowed", ""};
    }

public:
    RedirectValidator(const RedirectConfig& config) : config_(config) {}

    std::future<ValidationResult> validate_async(const AuthRequest& request) {
        return std::async(std::launch::async, [this, request]() -> ValidationResult {
            {
                std::lock_guard<std::mutex> lock(mtx_);
                auto it = cache_.find(request.redirect_uri);
                if (it != cache_.end()) {
                    return it->second;
                }
            }

            ValidationResult result = validate_internal(request.redirect_uri);

            {
                std::lock_guard<std::mutex> lock(mtx_);
                cache_[request.redirect_uri] = result;
            }
            return result;
        });
    }
};

class OAuthServer {
private:
    RedirectValidator validator_;

    std::string build_redirect_response(const AuthRequest& req, const std::string& code) {
        // Use the ORIGINAL redirect_uri (not normalized) for the actual redirect
        // This preserves any encoding the client expects
        std::string location = req.redirect_uri + "?code=" + code + "&state=" + req.state;
        return "HTTP/1.1 302 Found\r\nLocation: " + location + "\r\n\r\n";
    }

public:
    OAuthServer(const RedirectConfig& config) : validator_(config) {}

    std::future<std::string> handle_authorize(const AuthRequest& request) {
        return std::async(std::launch::async, [this, request]() -> std::string {
            auto validation_future = validator_.validate_async(request);
            ValidationResult result = validation_future.get();

            if (!result.valid) {
                return "HTTP/1.1 400 Bad Request\r\n\r\n" + result.error;
            }

            std::string auth_code = "generated_code_12345";
            return build_redirect_response(request, auth_code);
        });
    }
};

} // namespace oauth

int main() {
    oauth::RedirectConfig config;
    config.allowed_origins = {"app.example.com", "trusted.example.org"};
    config.enforce_https = true;
    config.allow_subdomains = true;

    oauth::OAuthServer server(config);

    oauth::AuthRequest req;
    req.client_id = "client123";
    req.redirect_uri = "https://app.example.com/callback";
    req.state = "random_state_value";
    req.scope = "openid profile";

    auto response_future = server.handle_authorize(req);
    std::cout << response_future.get() << std::endl;

    return 0;
}
